<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MOONCAKE_GLOBAL_SEGMENT_SIZE=$((32&lt;&lt;30)) </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
